import { Server } from "@modelcontextprotocol/sdk/server/index.js";
import { StdioServerTransport } from "@modelcontextprotocol/sdk/server/stdio.js";
import {
  CallToolRequestSchema,
  ListToolsRequestSchema,
} from "@modelcontextprotocol/sdk/types.js";
import { ArtifactStore } from "./artifact-store.js";
import { SearchEngine } from "./search.js";
import { CapabilityManager } from "./capabilities.js";
import { GitHubIntegration } from "./github-integration.js";
import { handlers, toolDefinitions, initializeHandlers } from "./handlers/index.js";
import config from "../config/default.js";
import * as http from "http";
import * as url from "url";

// Initialize components
const store = new ArtifactStore(config.storage.basePath);
const searchEngine = new SearchEngine(store);
const capabilityManager = new CapabilityManager();
const githubIntegration = new GitHubIntegration(store);

// Initialize handlers with dependencies
initializeHandlers(store, searchEngine, capabilityManager, githubIntegration);

// Create MCP server
const server = new Server(
  {
    name: "artifact-engine",
    version: "1.0.0",
  },
  {
    capabilities: {
      tools: {},
    },
  }
);

// Register tool list handler
server.setRequestHandler(ListToolsRequestSchema, async () => {
  return {
    tools: toolDefinitions,
  };
});

// Register tool call handler
server.setRequestHandler(CallToolRequestSchema, async (request) => {
  const { name, arguments: args } = request.params;

  const handler = handlers[name];
  if (!handler) {
    throw new Error(`Unknown tool: ${name}`);
  }

  return handler(args || {});
});

// HTTP Server for health checks and direct API access
function createHttpServer() {
  return http.createServer(async (req, res) => {
    const parsedUrl = url.parse(req.url || "", true);

    // CORS headers
    res.setHeader("Access-Control-Allow-Origin", "*");
    res.setHeader("Access-Control-Allow-Methods", "GET, POST, OPTIONS");
    res.setHeader("Access-Control-Allow-Headers", "Content-Type");

    if (req.method === "OPTIONS") {
      res.writeHead(200);
      res.end();
      return;
    }

    // Health check endpoint
    if (parsedUrl.pathname === "/health") {
      res.writeHead(200, { "Content-Type": "application/json" });
      res.end(JSON.stringify({ 
        status: "healthy", 
        service: "artifact-engine",
        version: "1.0.0",
        timestamp: new Date().toISOString()
      }));
      return;
    }

    // Tool execution endpoint
    if (parsedUrl.pathname === "/tool" && req.method === "POST") {
      let body = "";
      req.on("data", chunk => { body += chunk; });
      req.on("end", async () => {
        try {
          const { tool, arguments: args } = JSON.parse(body);
          const handler = handlers[tool];
          if (!handler) {
            res.writeHead(404, { "Content-Type": "application/json" });
            res.end(JSON.stringify({ error: `Unknown tool: ${tool}` }));
            return;
          }
          const result = await handler(args || {});
          res.writeHead(200, { "Content-Type": "application/json" });
          res.end(JSON.stringify(result));
        } catch (error) {
          res.writeHead(500, { "Content-Type": "application/json" });
          res.end(JSON.stringify({ error: String(error) }));
        }
      });
      return;
    }

    res.writeHead(404, { "Content-Type": "application/json" });
    res.end(JSON.stringify({ error: "Not found" }));
  });
}

// Main entry point
async function main() {
  const args = process.argv.slice(2);

  if (args.includes("--http")) {
    // HTTP mode for direct API access
    const httpServer = createHttpServer();
    const port = parseInt(process.env.PORT || "3002", 10);
    httpServer.listen(port, () => {
      console.log(`Artifact Engine HTTP server running on port ${port}`);
    });
  } else {
    // Default: MCP stdio mode
    const transport = new StdioServerTransport();
    await server.connect(transport);
    console.error("Artifact Engine MCP server running on stdio");
  }
}

main().catch(console.error);

export { store, searchEngine, capabilityManager, githubIntegration, server };

